package net.officefloor.hq.app.role;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRole {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RoleRequest request, Out<RoleInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.by());
        String user = request == null || request.user() == null ? "" : request.user().trim();
        if (user.isEmpty()) {
            throw new InvalidSheetException("A user name is required");
        }
        String text = request.role() == null ? "" : request.role().trim();
        Role role = Role.of(text);
        if (role == null) {
            throw new InvalidSheetException("The role must be clerk, steward or viewer");
        }
        body.set(new RoleInput(user, role, request.by()));
    }
}
package net.officefloor.hq.app.role;

import java.util.Locale;

/** A user's role on a sheet: every name is a clerk unless assigned otherwise. A clerk settles only
 *  claims within the sheet's clerk limit; a steward settles any. A viewer sees everything and may
 *  change nothing. */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as the screen and the audit file show it: clerk, steward or viewer. */
    public String shown() {
        return name().toLowerCase(Locale.ROOT);
    }

    /** The role named by the text (clerk, steward or viewer), or null when it names none. */
    public static Role of(String text) {
        for (Role r : values()) {
            if (r.shown().equals(text)) {
                return r;
            }
        }
        return null;
    }
}
package net.officefloor.hq.app.role;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The roles assigned per sheet. A user name with none assigned is a clerk; one with a delegation of the
 *  steward role in force on the sheet's today acts as a steward (see {@link DelegationStore}). */
@Repository
public class RoleStore {

    private final JdbcTemplate jdbc;
    private final DelegationStore delegations;
    private final SheetStore sheets;

    public RoleStore(JdbcTemplate jdbc, DelegationStore delegations, SheetStore sheets) {
        this.jdbc = jdbc;
        this.delegations = delegations;
        this.sheets = sheets;
    }

    /** Every role assigned on the sheet, by user name. */
    public List<RoleResponse> list(String sheetId) {
        return listFrom(sheetId, "sheet_role");
    }

    /** Every role assigned on the sheet at the end of the date (see {@link History}), by user name. */
    public List<RoleResponse> listAsOf(String sheetId, LocalDate date) {
        return listFrom(sheetId, History.asOf("sheet_role", "sheet_id, user_name", date));
    }

    private List<RoleResponse> listFrom(String sheetId, String table) {
        return jdbc.query("SELECT user_name, role FROM " + table + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).shown()),
                sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force, else
     *  the role assigned. */
    public Role find(String sheetId, String user) {
        return delegations.delegator(sheetId, user) != null ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's role as assigned on the sheet, delegations aside: clerk unless assigned otherwise. */
    public Role assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : Role.valueOf(found.get(0));
    }

    /** Refuses any change to an archived sheet, and any change by a viewer: a viewer may change nothing
     *  on the sheet. */
    public void refuseChange(String sheetId, String user) throws InvalidSheetException {
        sheets.refuseArchived(sheetId);
        if (find(sheetId, user == null ? "" : user.trim()) == Role.VIEWER) {
            throw new InvalidSheetException("A viewer may change nothing");
        }
    }

    public void set(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A user name's role on the sheet. A name with none assigned is a clerk; a viewer may change nothing. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward', 'viewer'] as const;

/** Under the sheet's key, so loading the sheet again re-reads its roles. */
export const rolesKey = (sheet: string) => [...sheetKey(sheet), 'roles'] as const;

export function useRoles(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(rolesKey(sheet), asOf),
    queryFn: () => getJson<Role[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/roles`, asOf)),
    enabled: sheet !== '',
  });
}

/** The steward role delegated to `user` by the steward `by` for from..to (yyyy-mm-dd), inclusive. */
export type Delegation = { user: string; from: string; to: string; by: string };

export const delegationsKey = (sheet: string) => [...sheetKey(sheet), 'delegations'] as const;

export function useDelegations(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(delegationsKey(sheet), asOf),
    queryFn: () => getJson<Delegation[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/delegations`, asOf)),
    enabled: sheet !== '',
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Role, ROLES, rolesKey, useRoles } from './roles';

// The roles assigned on the sheet (any other name is a clerk), and the form that assigns one.
function Roles() {
  const [by] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const roles = useRoles(sheet);
  const [user, setUser] = useState('');
  const [role, setRole] = useState('');
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: (r: { user: string; role: string }) =>
      postJson<Role>(`/api/sheets/${encodeURIComponent(sheet)}/roles`, { ...r, by }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: rolesKey(sheet) });
      setUser('');
      setRole('');
    },
  });
  const submit = useSubmitOnce(save);

  return (
    <section data-testid="roles">
      <h2>Roles</h2>
      <table>
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="role-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ user, role });
        }}
      >
        <input
          data-testid="role-form-user"
          placeholder="User name"
          value={user}
          onChange={(e) => {
            setUser(e.target.value);
            save.reset();
          }}
        />
        <input
          data-testid="role-form-role"
          placeholder={ROLES.join(' or ')}
          list="role-form-roles"
          value={role}
          onChange={(e) => {
            setRole(e.target.value);
            save.reset();
          }}
        />
        <datalist id="role-form-roles">
          {ROLES.map((r) => (
            <option key={r} value={r} />
          ))}
        </datalist>
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {save.isError && (
          <span data-testid="role-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The role was refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 50, Component: Roles });
-- The roles the sheet assigns: a user name with no row here is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(32)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's settings, by key; a null value is blank (for clerk-limit: no limit). A key with no
-- row here has never been set.
CREATE TABLE sheet_setting (
    sheet_id    VARCHAR(255) NOT NULL,
    setting_key VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key)
);

